#include <array>
#include <vector>
#include <cstddef>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel default(none) shared(x, bins, n)
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const double value = x[static_cast<std::size_t>(i)];

            // Values are specified to be in [0, 100]. Clamp 100 into the last bin.
            if (value >= 0.0) {
                std::size_t idx = static_cast<std::size_t>(value / 10.0);
                if (idx > 9) {
                    idx = 9;
                }
                ++local_bins[idx];
            }
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
